## 2. Full-Text Indexing Engine Module

```csharp
// ITextIndexingEngine.cs
public interface ITextIndexingEngine
{
    Task IndexDocumentAsync(string documentId, Stream contentStream, CancellationToken cancellationToken);
    Task<IEnumerable<SearchResult>> SearchAsync(string query, int maxResults, CancellationToken cancellationToken);
    Task UpdateDocumentAsync(string documentId, Stream contentStream, CancellationToken cancellationToken);
}

// TextIndexingEngine.cs
public class TextIndexingEngine : ITextIndexingEngine
{
    private readonly IInvertedIndex _invertedIndex;
    private readonly ITokenizer _tokenizer;
    private readonly ILogger<TextIndexingEngine> _logger;

    public TextIndexingEngine(
        IInvertedIndex invertedIndex,
        ITokenizer tokenizer,
        ILogger<TextIndexingEngine> logger)
    {
        _invertedIndex = invertedIndex ?? throw new ArgumentNullException(nameof(invertedIndex));
        _tokenizer = tokenizer ?? throw new ArgumentNullException(nameof(tokenizer));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task IndexDocumentAsync(
        string documentId,
        Stream contentStream,
        CancellationToken cancellationToken)
    {
        try
        {
            // Extract text from the document
            var text = await ExtractTextFromDocumentAsync(contentStream, cancellationToken);

            // Tokenize the text
            var tokens = _tokenizer.Tokenize(text);

            // Update the inverted index
            await _invertedIndex.AddOrUpdateDocumentAsync(documentId, tokens, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error indexing document {DocumentId}", documentId);
            throw;
        }
    }

    private async Task<string> ExtractTextFromDocumentAsync(Stream stream, CancellationToken cancellationToken)
    {
        // Implementation for extracting text from different document types
        // Could use libraries like PdfSharp, OpenXML, etc.
        return await new StreamReader(stream).ReadToEndAsync(cancellationToken);
    }

    public async Task<IEnumerable<SearchResult>> SearchAsync(
        string query,
        int maxResults,
        CancellationToken cancellationToken)
    {
        try
        {
            // Tokenize the search query
            var queryTokens = _tokenizer.Tokenize(query);

            // Perform search using inverted index
            var results = await _invertedIndex.SearchAsync(queryTokens, maxResults, cancellationToken);

            return results;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error performing search");
            throw;
        }
    }

    public async Task UpdateDocumentAsync(
        string documentId,
        Stream contentStream,
        CancellationToken cancellationToken)
    {
        // Remove old document from index
        await _invertedIndex.RemoveDocumentAsync(documentId, cancellationToken);

        // Re-index the document
        await IndexDocumentAsync(documentId, contentStream, cancellationToken);
    }
}

// IInvertedIndex.cs
public interface IInvertedIndex
{
    Task AddOrUpdateDocumentAsync(string documentId, IEnumerable<string> tokens, CancellationToken cancellationToken);
    Task RemoveDocumentAsync(string documentId, CancellationToken cancellationToken);
    Task<IEnumerable<SearchResult>> SearchAsync(IEnumerable<string> queryTokens, int maxResults, CancellationToken cancellationToken);
}

// InvertedIndex.cs
public class InvertedIndex : IInvertedIndex
{
    private readonly ConcurrentDictionary<string, HashSet<string>> _documentToTerms;
    private readonly ConcurrentDictionary<string, HashSet<string>> _termToDocuments;
    private readonly object _lock = new object();

    public InvertedIndex()
    {
        _documentToTerms = new ConcurrentDictionary<string, HashSet<string>>();
        _termToDocuments = new ConcurrentDictionary<string, HashSet<string>>();
    }

    public async Task AddOrUpdateDocumentAsync(
        string documentId,
        IEnumerable<string> tokens,
        CancellationToken cancellationToken)
    {
        // Remove old terms if document exists
        if (_documentToTerms.TryGetValue(documentId, out var oldTerms))
        {
            foreach (var term in oldTerms)
            {
                if (_termToDocuments.TryGetValue(term, out var docs))
                {
                    var newDocs = new HashSet<string>(docs);
                    newDocs.Remove(documentId);
                    _termToDocuments[term] = newDocs;
                }
            }
        }

        // Add new terms
        var newTerms = new HashSet<string>(tokens);
        _documentToTerms[documentId] = newTerms;

        foreach (var term in newTerms)
        {
            if (!_termToDocuments.TryGetValue(term, out var docs))
            {
                docs = new HashSet<string>();
                _termToDocuments[term] = docs;
            }
            docs.Add(documentId);
        }
    }

    public async Task RemoveDocumentAsync(string documentId, CancellationToken cancellationToken)
    {
        if (_documentToTerms.TryRemove(documentId, out var terms))
        {
            foreach (var term in terms)
            {
                if (_termToDocuments.TryGetValue(term, out var docs))
                {
                    docs.Remove(documentId);
                    if (docs.Count == 0)
                    {
                        _termToDocuments.TryRemove(term, out _);
                    }
                }
            }
        }
    }

    public async Task<IEnumerable<SearchResult>> SearchAsync(
        IEnumerable<string> queryTokens,
        int maxResults,
        CancellationToken cancellationToken)
    {
        var results = new List<SearchResult>();

        foreach (var term in queryTokens)
        {
            if (_termToDocuments.TryGetValue(term, out var documents))
            {
                foreach (var docId in documents)
                {
                    if (!_documentToTerms.TryGetValue(docId, out var docTerms))
                    {
                        continue;
                    }

                    // Calculate score (simple TF-IDF implementation)
                    var score = CalculateScore(docTerms, queryTokens);

                    results.Add(new SearchResult(docId, score));
                }
            }
        }

        // Sort by score and return top results
        return results.OrderByDescending(r => r.Score)
                     .Take(maxResults)
                     .ToList();
    }

    private double CalculateScore(HashSet<string> docTerms, IEnumerable<string> queryTerms)
    {
        // Simple scoring implementation
        var intersection = docTerms.Intersect(queryTerms).Count();
        return intersection / Math.Max(1, docTerms.Count);
    }
}

// ITokenizer.cs
public interface ITokenizer
{
    IEnumerable<string> Tokenize(string text);
}

// SimpleTokenizer.cs
public class SimpleTokenizer : ITokenizer
{
    public IEnumerable<string> Tokenize(string text)
    {
        // Basic tokenization - could be enhanced with stemming, stop word removal, etc.
        return text.ToLower()
                   .Split(new[] {' ', '.', ',', ';', ':', '!', '?', '\n', '\r', '\t'},
                          StringSplitOptions.RemoveEmptyEntries)
                   .Where(t => !string.IsNullOrWhiteSpace(t))
                   .Select(t => t.Trim());
    }
}

// SearchResult.cs
public class SearchResult
{
    public string DocumentId { get; }
    public double Score { get; }

    public SearchResult(string documentId, double score)
    {
        DocumentId = documentId;
        Score = score;
    }
}
