## 3. Role-Based Access Control (RBAC) Subsystem

```csharp
// IRbacService.cs
public interface IRbacService
{
    Task<bool> CheckPermissionAsync(string userId, string resourceId, string action, CancellationToken cancellationToken);
    Task<IEnumerable<string>> GetUserRolesAsync(string userId, CancellationToken cancellationToken);
    Task<IEnumerable<string>> GetResourcePermissionsAsync(string resourceId, CancellationToken cancellationToken);
    Task AssignRoleToUserAsync(string userId, string roleName, CancellationToken cancellationToken);
    Task RemoveRoleFromUserAsync(string userId, string roleName, CancellationToken cancellationToken);
}

// RbacService.cs
public class RbacService : IRbacService
{
    private readonly IRoleStore _roleStore;
    private readonly IUserStore _userStore;
    private readonly IResourceStore _resourceStore;
    private readonly ILogger<RbacService> _logger;

    public RbacService(
        IRoleStore roleStore,
        IUserStore userStore,
        IResourceStore resourceStore,
        ILogger<RbacService> logger)
    {
        _roleStore = roleStore ?? throw new ArgumentNullException(nameof(roleStore));
        _userStore = userStore ?? throw new ArgumentNullException(nameof(userStore));
        _resourceStore = resourceStore ?? throw new ArgumentNullException(nameof(resourceStore));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<bool> CheckPermissionAsync(
        string userId,
        string resourceId,
        string action,
        CancellationToken cancellationToken)
    {
        try
        {
            // Get user's roles
            var userRoles = await GetUserRolesAsync(userId, cancellationToken);

            // Get resource permissions
            var resourcePermissions = await GetResourcePermissionsAsync(resourceId, cancellationToken);

            // Check if any role has the required permission
            foreach (var role in userRoles)
            {
                if (resourcePermissions.Contains(role + ":" + action))
                {
                    return true;
                }
            }

            return false;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error checking permission for user {UserId} on resource {ResourceId}", userId, resourceId);
            throw;
        }
    }

    public async Task<IEnumerable<string>> GetUserRolesAsync(string userId, CancellationToken cancellationToken)
    {
        return await _userStore.GetRolesAsync(userId, cancellationToken);
    }

    public async Task<IEnumerable<string>> GetResourcePermissionsAsync(string resourceId, CancellationToken cancellationToken)
    {
        return await _resourceStore.GetPermissionsAsync(resourceId, cancellationToken);
    }

    public async Task AssignRoleToUserAsync(string userId, string roleName, CancellationToken cancellationToken)
    {
        await _userStore.AddToRoleAsync(userId, roleName, cancellationToken);
    }

    public async Task RemoveRoleFromUserAsync(string userId, string roleName, CancellationToken cancellationToken)
    {
        await _userStore.RemoveFromRoleAsync(userId, roleName, cancellationToken);
    }
}

// IRoleStore.cs
public interface IRoleStore
{
    Task<IEnumerable<string>> GetRolesAsync(string userId, CancellationToken cancellationToken);
    Task AddToRoleAsync(string userId, string roleName, CancellationToken cancellationToken);
    Task RemoveFromRoleAsync(string userId, string roleName, CancellationToken cancellationToken);
}

// InMemoryRoleStore.cs (example implementation)
public class InMemoryRoleStore : IRoleStore
{
    private readonly ConcurrentDictionary<string, HashSet<string>> _userRoles =
        new ConcurrentDictionary<string, HashSet<string>>();

    public Task<IEnumerable<string>> GetRolesAsync(string userId, CancellationToken cancellationToken)
    {
        if (_userRoles.TryGetValue(userId, out var roles))
        {
            return Task.FromResult<IEnumerable<string>>(roles);
        }
        return Task.FromResult<IEnumerable<string>>(Array.Empty<string>());
    }

    public Task AddToRoleAsync(string userId, string roleName, CancellationToken cancellationToken)
    {
        if (!_userRoles.TryGetValue(userId, out var roles))
        {
            roles = new HashSet<string>();
            _userRoles.TryAdd(userId, roles);
        }

        roles.Add(roleName);
        return Task.CompletedTask;
    }

    public Task RemoveFromRoleAsync(string userId, string roleName, CancellationToken cancellationToken)
    {
        if (_userRoles.TryGetValue(userId, out var roles))
        {
            roles.Remove(roleName);
        }
        return Task.CompletedTask;
    }
}

// IUserStore.cs
public interface IUserStore
{
    Task<IEnumerable<string>> GetRolesAsync(string userId, CancellationToken cancellationToken);
    Task AddToRoleAsync(string userId, string roleName, CancellationToken cancellationToken);
    Task RemoveFromRoleAsync(string userId, string roleName, CancellationToken cancellationToken);
}

// IResourceStore.cs
public interface IResourceStore
{
    Task<IEnumerable<string>> GetPermissionsAsync(string resourceId, CancellationToken cancellationToken);
    Task AddPermissionAsync(string resourceId, string permission, CancellationToken cancellationToken);
    Task RemovePermissionAsync(string resourceId, string permission, CancellationToken cancellationToken);
}

// InMemoryResourceStore.cs (example implementation)
public class InMemoryResourceStore : IResourceStore
{
    private readonly ConcurrentDictionary<string, HashSet<string>> _resourcePermissions =
        new ConcurrentDictionary<string, HashSet<string>>();

    public Task<IEnumerable<string>> GetPermissionsAsync(string resourceId, CancellationToken cancellationToken)
    {
        if (_resourcePermissions.TryGetValue(resourceId, out var permissions))
        {
            return Task.FromResult<IEnumerable<string>>(permissions);
        }
        return Task.FromResult<IEnumerable<string>>(Array.Empty<string>());
    }

    public Task AddPermissionAsync(string resourceId, string permission, CancellationToken cancellationToken)
    {
        if (!_resourcePermissions.TryGetValue(resourceId, out var permissions))
        {
            permissions = new HashSet<string>();
            _resourcePermissions.TryAdd(resourceId, permissions);
        }

        permissions.Add(permission);
        return Task.CompletedTask;
    }

    public Task RemovePermissionAsync(string resourceId, string permission, CancellationToken cancellationToken)
    {
        if (_resourcePermissions.TryGetValue(resourceId, out var permissions))
        {
            permissions.Remove(permission);
        }
        return Task.CompletedTask;
    }
}
